n=28; g=[[0]*n for _ in range(n)]
for i in [4,9,14,19,24]:
 for j in range(n): g[i][j]=8; g[j][i]=8
# tiles with line color; coordinates of tile starts r,c; cells interiors only
paint={}
for c in range(5): paint[(1,c)]=2
for r in range(1,4): paint[(r,0)]=2
for r in range(5):
 k=(r,2); paint[k]=paint.get(k,0)+3
# if mixed sum becomes 5? output demonstrates color 6 when overlap 2 and3. set
paint[(1,2)]=6
for (tr,tc),v in paint.items():
 rs=range(tr*5,tr*5+4); cs=range(tc*5,tc*5+4)
 for r in rs:
  for c in cs: g[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in g))
